          '.hint { color: #5b6675; font-size: 0.85rem; margin-top: 8px; }',
          '#log { list-style: none; margin: 16px 0 0; padding: 0; width: 100%; max-width: 360px; }',
          '#log li { background: #fff; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px;',
