          '    <button id="minus" aria-label="Restar uno">−1</button>',
          '    <button id="plus" aria-label="Sumar uno">+1</button>',
          '  </div>',
          '  <button id="reset" class="ghost" style="margin-top:10px">Reiniciar</button>',
          '  <p class="hint">Todos los miembros del chat ven este contador en tiempo real.</p>',
          '  <ul id="log"></ul>',
          '  <script>',
          "'use strict';",
          "var hasWebxdc = typeof window.webxdc !== 'undefined';",
          'var counter = 0;',
          '',
          'function render() {',
          "  document.getElementById('counter').textContent = String(counter);",
          '}',
          '',
          'function addLog(text) {',
          '  var li = document.createElement("li");',
          '  li.textContent = text;',
          '  var log = document.getElementById("log");',
          '  log.insertBefore(li, log.firstChild);',
          '  while (log.children.length > 8) log.removeChild(log.lastChild);',
          '}',
          '',
          'function apply(update) {',
          '  var p = update && update.payload;',
          "  if (p && typeof p.counter === 'number') {",
          '    counter = p.counter;',
          '    render();',
          '    addLog((p.who || "?") + " → " + counter);',
          '  }',
          '}',
          '',
          'function send(kind) {',
          "  counter = kind === 'reset' ? 0 : counter + (kind === 'plus' ? 1 : -1);",
          '  render();',
