          '  padding: 12px 22px; min-height: 48px; background: #2f9e44; color: #fff; cursor: pointer; }',
          '.main-btns button.stop { background: #c2255c; }',
          '.hint { color: #8b93a3; font-size: 0.85rem; margin-top: 12px; text-align: center; }',
          '  </style>',
          '</head>',
          '<body>',
          '  <h1>⏱ Temporizador</h1>',
          '  <div id="mode-sw" class="seg">',
          '    <button data-mode="stopwatch" class="on">Cronómetro</button>',
