  const tplNotes = {
    id: 'notes',
    cat: 'productivity',
    es: { name: 'Notas', desc: 'Notas personales guardadas en localStorage. La plantilla más sencilla de leer: perfecta como primer proyecto para modificar.' },
    en: { name: 'Notes', desc: 'Personal notes stored in localStorage. The simplest template to read: perfect as a first project to tweak.' },
    createFiles: function () {
      return {
        'index.html': [
          '<!DOCTYPE html>',
          '<html lang="es">',
          '<head>',
          '  <meta charset="utf-8">',
          '  <meta name="viewport" content="width=device-width, initial-scale=1">',
          '  <title>Mis notas</title>',
          '  <script src="webxdc.js"><\/script>',
          '  <style>',
          '*, *::before, *::after { box-sizing: border-box; }',
          'body { margin: 0; font-family: system-ui, sans-serif; background: #f2f4f8; color: #1c2430; padding: 16px; }',
          'h1 { font-size: 1.2rem; margin: 0 0 12px; }',
          'textarea { width: 100%; min-height: 120px; font: inherit; padding: 10px; border: 1px solid #c3ccda;',
          '  border-radius: 10px; resize: vertical; }',
          '.row { display: flex; gap: 8px; margin: 10px 0; }',
          'button { font: inherit; border: 0; border-radius: 10px; padding: 10px 16px; min-height: 44px;',
          '  background: #3b5bdb; color: #fff; cursor: pointer; }',
          'button.ghost { background: #dde3ee; color: #1c2430; }',
          '#list { list-style: none; margin: 0; padding: 0; }',
          '#list li { background: #fff; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px;',
          '  white-space: pre-wrap; overflow-wrap: anywhere; box-shadow: 0 1px 2px rgba(0,0,0,.06); }',
          '#list li .del { float: right; background: none; color: #c2255c; padding: 0 6px; min-height: 32px; }',
          '  </style>',
          '</head>',
          '<body>',
          '  <h1>Mis notas</h1>',
          '  <textarea id="note" placeholder="Escribe una nota…"></textarea>',
          '  <div class="row">',
          '    <button id="save">Guardar nota</button>',
          '    <button id="clear" class="ghost">Vaciar</button>',
          '  </div>',
          '  <ul id="list"></ul>',
          '  <script>',
          "'use strict';",
          '/* Notas locales: se guardan en este dispositivo con localStorage. */',
          'var KEY = "wcs-notes";',
          'var notes = [];',
          'try { notes = JSON.parse(localStorage.getItem(KEY) || "[]"); } catch (e) { notes = []; }',
          '',
          'function persist() {',
          '  try { localStorage.setItem(KEY, JSON.stringify(notes)); } catch (e) { alert("No se pudo guardar (¿almacenamiento lleno?)"); }',
          '}',
          '',
          'function render() {',
          '  var list = document.getElementById("list");',
          '  list.textContent = "";',
          '  notes.map(function (n, i) {',
          '    var li = document.createElement("li");',
          '    var del = document.createElement("button");',
          '    del.className = "del"; del.textContent = "✕";',
          '    del.setAttribute("aria-label", "Borrar nota");',
          '    del.addEventListener("click", function () { notes.splice(i, 1); persist(); render(); });',
          '    li.appendChild(del);',
          '    li.appendChild(document.createTextNode(n));',
          '    list.appendChild(li);',
          '  });',
          '}',
          '',
          'document.getElementById("save").addEventListener("click", function () {',
          '  var t = document.getElementById("note").value.trim();',
          '  if (!t) return;',
          '  notes.unshift(t);',
          '  document.getElementById("note").value = "";',
          '  persist(); render();',
          '});',
          '',
          'document.getElementById("clear").addEventListener("click", function () {',
          '  if (notes.length && confirm("¿Vaciar todas las notas?")) { notes = []; persist(); render(); }',
          '});',
          '',
          'render();',
          '  <\/script>',
          '</body>',
          '</html>',
          ''
        ].join('\n')
      };
    }
  };

