  const tplPoll = {
    id: 'poll',
    cat: 'education',
    es: { name: 'Encuesta del chat', desc: 'Encuesta con recuento en vivo: cada miembro vota una vez y todos ven los resultados. Ejemplo educativo de cómo procesar el historial completo de updates (serial 0).' },
    en: { name: 'Chat poll', desc: 'Poll with live tally: each member votes once and everyone sees results. Educational example of processing the full update history (serial 0).' },
    createFiles: function () {
      return {
        'index.html': [
          '<!DOCTYPE html>',
          '<html lang="es">',
          '<head>',
          '  <meta charset="utf-8">',
          '  <meta name="viewport" content="width=device-width, initial-scale=1">',
          '  <title>Encuesta</title>',
          '  <script src="webxdc.js"><\/script>',
          '  <style>',
          '*, *::before, *::after { box-sizing: border-box; }',
          'body { margin: 0; font-family: system-ui, sans-serif; background: #f2f4f8; color: #1c2430; padding: 16px; }',
          'h1 { font-size: 1.2rem; margin: 0 0 4px; }',
          '.hint { color: #5b6675; font-size: 0.85rem; margin: 4px 0 14px; }',
          '.opt { display: block; width: 100%; text-align: left; font: inherit; border: 2px solid #c3ccda;',
          '  border-radius: 12px; padding: 12px 14px; min-height: 48px; margin-bottom: 8px;',
          '  background: #fff; color: #1c2430; cursor: pointer; }',
          '.opt.mine { border-color: #3b5bdb; background: #edf2ff; }',
          '.bar { height: 10px; border-radius: 999px; background: #dbe2ee; margin-top: 8px; overflow: hidden; }',
          '.bar > span { display: block; height: 100%; background: #3b5bdb; width: 0; transition: width .3s; }',
          '.meta { font-size: .85rem; color: #5b6675; margin-top: 4px; }',
          '  </style>',
          '</head>',
          '<body>',
          '  <h1 id="question">¿Película o libro?</h1>',
          '  <p class="hint">Cada persona vota una vez. Resultados en vivo.</p>',
          '  <div id="options"></div>',
          '  <p class="meta" id="total"></p>',
          '  <script>',
          "'use strict';",
          '/* --- Configura aquí tu encuesta --------------------------------- */',
          'var QUESTION = "¿Película o libro?";',
          'var OPTIONS = ["Película", "Libro", "Ambos"];',
          '/* ---------------------------------------------------------------- */',
          '',
          "var hasWebxdc = typeof window.webxdc !== 'undefined';",
          'var votes = {};  /* addr -> índice de opción (último voto gana) */',
          'var names = {};  /* addr -> nombre visible */',
          '',
          'function myAddr() {',
          '  return hasWebxdc ? window.webxdc.selfAddr : "local";',
          '}',
          '',
          'function render() {',
          '  var box = document.getElementById("options");',
          '  box.textContent = "";',
          '  var counts = OPTIONS.map(function () { return 0; });',
          '  Object.keys(votes).forEach(function (addr) { counts[votes[addr]]++; });',
          '  var total = Object.keys(votes).length;',
          '  var mine = votes[myAddr()];',
          '',
          '  OPTIONS.forEach(function (opt, i) {',
          '    var btn = document.createElement("button");',
          '    btn.className = "opt" + (mine === i ? " mine" : "");',
          '    btn.textContent = opt;',
          '    var bar = document.createElement("span");',
          '    bar.className = "bar";',
          '    var fill = document.createElement("span");',
          '    fill.style.width = total ? Math.round(counts[i] * 100 / total) + "%" : "0";',
          '    bar.appendChild(fill);',
          '    var meta = document.createElement("div");',
          '    meta.className = "meta";',
          '    meta.textContent = counts[i] + " voto" + (counts[i] === 1 ? "" : "s") +',
          '      " · " + (total ? Math.round(counts[i] * 100 / total) : 0) + "%";',
          '    btn.appendChild(bar);',
          '    btn.appendChild(meta);',
          '    btn.addEventListener("click", function () { vote(i); });',
          '    box.appendChild(btn);',
          '  });',
          '',
          '  document.getElementById("question").textContent = QUESTION;',
          '  document.getElementById("total").textContent =',
          '    total ? total + " persona" + (total === 1 ? "" : "s") + " ya votaron." : "Aún nadie ha votado.";',
          '}',
          '',
          'function vote(i) {',
          '  if (!hasWebxdc) { votes["local"] = i; render(); return; }',
          '  window.webxdc.sendUpdate({',
          '    payload: { type: "vote", option: i, addr: window.webxdc.selfAddr, name: window.webxdc.selfName },',
          '    info: "Voto: " + OPTIONS[i],',
          '    summary: Object.keys(votes).length + 1 + " votos"',
          '  }, "");',
          '}',
          '',
          '/* El historial completo de updates reconstruye los votos de todos. */',
          'function apply(update) {',
          '  var p = update && update.payload;',
          '  if (p && p.type === "vote" && typeof p.option === "number" && p.option >= 0 && p.option < OPTIONS.length) {',
          '    votes[p.addr || "?"] = p.option;',
          '    if (p.name) names[p.addr || "?"] = p.name;',
          '    render();',
          '  }',
          '}',
          '',
          'if (hasWebxdc) {',
          '  window.webxdc.setUpdateListener(function (update) {',
          '    (Array.isArray(update) ? update : [update]).forEach(apply);',
          '  }, 0);',
          '}',
          '',
          'render();',
          '  <\/script>',
          '</body>',
          '</html>',
          ''
        ].join('\n')
      };
    }
  };

